sys_script_fix.script:
(function run() {
  var gr = new GlideRecord('cmdb_ci_business_app');
  gr.query();
  while (gr.next()) {
    if (!gr.u_seq_interna) continue;
    var name = gr.name.split(' ')[0].slice(1);
    if (parseInt(name) == gr.u_seq_interna) continue;
    gr.u_seq_interna = name;
    gr.update();
  }
})();
